def oranges_brute(grid):
    from copy import deepcopy
    g = deepcopy(grid)
    n, m = len(g), len(g[0])
    minutes = 0
    def step():
        changed = False
        nxt = [row[:] for row in g]
        for i in range(n):
            for j in range(m):
                if g[i][j] == 2:
                    for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
                        ni, nj = i + di, j + dj
                        if 0 <= ni < n and 0 <= nj < m and g[ni][nj] == 1:
                            nxt[ni][nj] = 2
                            changed = True
        for i in range(n):
            g[i] = nxt[i]
        return changed
    while step():
        minutes += 1
    return -1 if any(1 in row for row in g) else minutes

from collections import deque

def oranges_rotting(grid):
    n, m = len(grid), len(grid[0])
    q = deque()
    fresh = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 2:
                q.append((i, j, 0))
            elif grid[i][j] == 1:
                fresh += 1
    ans = 0
    while q:
        i, j, t = q.popleft()
        for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == 1:
                grid[ni][nj] = 2
                fresh -= 1
                ans = t + 1
                q.append((ni, nj, t + 1))
    return -1 if fresh else ans
